                    while other < held.count {
                        let next = try held[other].__keyOrder(paths, at + 6)
                        if next == order { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 4]) }
                        if next > order { break }
                        other += 1
                    }
                    reader.seek(to: start)
                    if self.__botsPool.isEmpty { self.__botsPool.append(World_Bot()) }
                    try self.__botsPool[0].__readFields(&reader, paths, at + 6)
                }
            }
            var changedLeft = try reader.read(4, path: paths[at + 4])
            if changedLeft > 8 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 4]) }
            var changedCursor = reader.bitPosition
            if removedLeft == 0 && addedLeft == 0 && changedLeft == 0 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 4]) }
            if baselineCount - removedLeft + addedLeft > 8 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 4]) }
            self.bots.removeAll(keepingCapacity: true)
            var nextRemoved = try Self.__nextPosition(&reader, &removedCursor, &removedLeft, 3, paths[at + 4])
            var nextChanged = try Self.__nextPosition(&reader, &changedCursor, &changedLeft, 3, paths[at + 4])
            var addedOrder: UInt64 = 0
            if addedLeft > 0 {
                reader.seek(to: addedCursor)
                addedOrder = try World_Bot.__readKeyOrder(&reader, paths, at + 6)
            }
            for position in 0..<baselineCount {
                let element = held[Int(position)]
                let order = try element.__keyOrder(paths, at + 6)
                while addedLeft > 0 && addedOrder < order {
                    if self.bots.count == self.__botsPool.count { self.__botsPool.append(World_Bot()) }
                    let item = self.__botsPool[self.bots.count]
                    reader.seek(to: addedCursor)
                    try item.__readFields(&reader, paths, at + 6)
                    addedCursor = reader.bitPosition
                    self.bots.append(item)
                    addedLeft -= 1
                    if addedLeft > 0 { addedOrder = try World_Bot.__readKeyOrder(&reader, paths, at + 6) }
                }
                if position == nextRemoved {
                    if position == nextChanged { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 4]) }
                    nextRemoved = try Self.__nextPosition(&reader, &removedCursor, &removedLeft, 3, paths[at + 4])
                } else if position == nextChanged {
                    if self.bots.count == self.__botsPool.count { self.__botsPool.append(World_Bot()) }
                    let item = self.__botsPool[self.bots.count]
                    reader.seek(to: changedCursor)
                    if !(try item.__readDelta(element, &reader, paths, at + 6, true)) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 5]) }
                    changedCursor = reader.bitPosition
                    self.bots.append(item)
                    let before = nextChanged
                    nextChanged = try Self.__nextPosition(&reader, &changedCursor, &changedLeft, 3, paths[at + 4])
                    if nextChanged <= before { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 4]) }
                } else {
                    if self.bots.count == self.__botsPool.count { self.__botsPool.append(World_Bot()) }
                    let item = self.__botsPool[self.bots.count]
                    item.copy(from: element)
                    self.bots.append(item)
                }
            }
            // A changed position beyond the baseline was never reached.
            if nextChanged != UInt64.max { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 4]) }
            while addedLeft > 0 {
                if self.bots.count == self.__botsPool.count { self.__botsPool.append(World_Bot()) }
                let item = self.__botsPool[self.bots.count]
                reader.seek(to: addedCursor)
                try item.__readFields(&reader, paths, at + 6)
                addedCursor = reader.bitPosition
                self.bots.append(item)
                addedLeft -= 1
                if addedLeft > 0 { addedOrder = try World_Bot.__readKeyOrder(&reader, paths, at + 6) }
            }
            reader.seek(to: changedCursor)
        }

        private static func __setCount(_ writer: inout GesBitWriter, _ countBit: Int, _ count: UInt64, _ width: Int) {
            for bit in 0..<width where (count >> UInt64(bit)) & 1 != 0 { writer.setBit(countBit + bit) }
        }

        // The next position of a section, read at its cursor, or the largest number when the section has ended.
        private static func __nextPosition(_ reader: inout GesBitReader, _ cursor: inout Int, _ left: inout UInt64, _ width: Int, _ path: String) throws(GesWireError) -> UInt64 {
            if left == 0 { return .max }
            left -= 1
            reader.seek(to: cursor)
            let position = try reader.read(width, path: path)
            cursor = reader.bitPosition
            return position
        }

        private static func __wire0(_ value: Int64, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            if value < 0 || UInt64(bitPattern: value) &- 0 > 1000000 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 0]) }
            return UInt64(bitPattern: value) &- 0
        }

        private static func __read0(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(20, path: paths[at + 0])
            if wire > 1000000 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 0]) }
            return wire
        }

        private static func __value0(_ wire: UInt64) -> Int64 { Int64(bitPattern: 0 &+ wire) }

        private static func __wire2(_ value: Double, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            try GesWireRules.quantizedIndex(value, lowerValue: Double(bitPattern: 0x0000000000000000), upperValue: Double(bitPattern: 0x409f400000000000), tenPower: 1.0, numerator: 1.0, lower: 0, path: paths[at + 2])
        }

        private static func __read2(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(11, path: paths[at + 2])
            if wire > 2000 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 2]) }
            return wire
        }

        private static func __value2(_ wire: UInt64) -> Double { GesWireRules.quantizedValue(wire, lower: 0, numerator: 1, tenPower: 1.0) }

        private static func __wire3(_ value: Double, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            try GesWireRules.quantizedIndex(value, lowerValue: Double(bitPattern: 0x0000000000000000), upperValue: Double(bitPattern: 0x409f400000000000), tenPower: 1.0, numerator: 1.0, lower: 0, path: paths[at + 3])
        }

        private static func __read3(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(11, path: paths[at + 3])
            if wire > 2000 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 3]) }
            return wire
        }

        private static func __value3(_ wire: UInt64) -> Double { GesWireRules.quantizedValue(wire, lower: 0, numerator: 1, tenPower: 1.0) }

        func __same(_ other: World, _ paths: [String], _ at: Int) throws(GesWireError) -> Bool {
            if try Self.__wire0(self.tick, paths, at) != Self.__wire0(other.tick, paths, at) { return false }
            if try Self.__wire2(self.arena.x, paths, at) != Self.__wire2(other.arena.x, paths, at) { return false }
            if try Self.__wire3(self.arena.y, paths, at) != Self.__wire3(other.arena.y, paths, at) { return false }
            if self.bots.count != other.bots.count { return false }
            for index4 in 0..<self.bots.count {
                if !(try self.bots[index4].__same(other.bots[index4], paths, at + 6)) { return false }
            }
            if self.hasBadge != other.hasBadge { return false }
            if self.hasBadge {
                if !(try self.badge.__same(other.badge, paths, at + 20)) { return false }
            }
            return true
        }

        /// Copies the values of another record into the storage of this one, without allocating once it has grown.
        func copy(from other: World) {
            if self === other { return }
            self.tick = other.tick
            self.arena = other.arena
            self.bots.removeAll(keepingCapacity: true)
            for index4 in 0..<other.bots.count {
                if index4 == self.__botsPool.count { self.__botsPool.append(World_Bot()) }
                let item4 = self.__botsPool[index4]
                item4.copy(from: other.bots[index4])
                self.bots.append(item4)
            }
            self.hasBadge = other.hasBadge
            self.badge.copy(from: other.badge)
        }

        func __quantize(_ paths: [String], _ at: Int) throws(GesWireError) {
            self.arena.x = Self.__value2(try Self.__wire2(self.arena.x, paths, at))
            self.arena.y = Self.__value3(try Self.__wire3(self.arena.y, paths, at))
            for index4 in 0..<self.bots.count {
                try self.bots[index4].__quantize(paths, at + 6)
            }
            if self.hasBadge {
                try self.badge.__quantize(paths, at + 20)
            }
        }

        /// Returns whether another schema has the same wire values, so that it writes the same bytes.
        /// - Throws: `GesWireError` when a compared value has no wire value, such as a number outside its range.
        func wireEquals(_ other: World) throws(GesWireError) -> Bool {
            try __same(other, Self.__paths, 0)
        }

        /// Replaces every quantized value by the value its index decodes to, which a receiver reads.
        /// - Throws: `GesWireError` when a quantized value lies outside its range.
        func quantize() throws(GesWireError) {
            try __quantize(Self.__paths, 0)
        }

        /// Writes what differs from a baseline, the full record the receiver holds; `maxByteCount` bytes always suffice.
        /// - Returns: The number of bytes written.
        /// - Throws: `GesWireError` when a value does not fit its field, the keys differ, or the buffer is too small.
        func writeDelta(against baseline: World, into buffer: UnsafeMutableRawBufferPointer) throws(GesWireError) -> Int {
            var writer = GesBitWriter(into: buffer)
            _ = try __writeDelta(baseline, &writer, Self.__paths, 0, true)
            return try writer.finish()
        }

        /// Writes what differs from a baseline into a new array of its exact size.
        /// - Throws: `GesWireError` when a value does not fit its field or the keys differ.
        func deltaEncoded(against baseline: World) throws(GesWireError) -> [UInt8] {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(Self.maxByteCount, 1), alignment: 8)
            defer { buffer.deallocate() }
            let count = try writeDelta(against: baseline, into: buffer)
            return Array(buffer[0..<count])
        }

        /// Reads a delta against a baseline into this instance. After an error its values are unspecified.
        /// - Parameters:
        ///   - data: The delta; it may continue after it.
        ///   - baseline: The baseline, another instance.
        ///   - byteLimit: An optional limit on the bytes of this delta.
        /// - Returns: The number of bytes the delta occupies.
        /// - Throws: `GesWireError` when the data is no valid delta for this baseline.
        @discardableResult
        func readDelta(from data: UnsafeRawBufferPointer, against baseline: World, byteLimit: Int = .max) throws(GesWireError) -> Int {
            if self === baseline { throw GesWireError(code: GesWireError.overlappingBuffers, path: "") }
            #if DEBUG || GES_CHECK_SHARING
            self.__mark(true)
            let shared = baseline.__holds()
            self.__mark(false)
            if shared { throw GesWireError(code: GesWireError.overlappingBuffers, path: "") }
            #endif
            var reader = GesBitReader(data: data, byteLimit: byteLimit)
            _ = try __readDelta(baseline, &reader, Self.__paths, 0, true)
            return try reader.finish()
        }

        /// Reads a delta from bytes against a baseline into this instance. After an error its values are unspecified.
        /// - Returns: The number of bytes the delta occupies.
        /// - Throws: `GesWireError` when the bytes are no valid delta for this baseline.
        @discardableResult
        func readDelta(from bytes: [UInt8], against baseline: World, byteLimit: Int = .max) throws(GesWireError) -> Int {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
            defer { buffer.deallocate() }
            buffer.copyBytes(from: bytes)
            return try readDelta(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), against: baseline, byteLimit: byteLimit)
        }

        func __writeDelta(_ baseline: World, _ writer: inout GesBitWriter, _ paths: [String], _ at: Int, _ top: Bool) throws(GesWireError) -> Bool {
            let first = writer.bitPosition
            var left = 4
            while left > 0 {
                try writer.write(0, width: Swift.min(left, 64))
                left -= 64
            }
            var changed = false
            var ordinal = 0
            do {
                var set0 = false
                do {
                    let value0 = try Self.__wire0(self.tick, paths, at)
                    let held0 = try Self.__wire0(baseline.tick, paths, at)
                    if value0 != held0 {
                        try writer.write(value0, width: 20)
                        set0 = true
                    }
                }
                if set0 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set1 = false
                do {
                    let first1 = writer.bitPosition
                    try writer.write(0, width: 2)
                    do {
                        var set2 = false
                        do {
                            let value2 = try Self.__wire2(self.arena.x, paths, at)
                            let held2 = try Self.__wire2(baseline.arena.x, paths, at)
                            if value2 != held2 {
                                try writer.write(value2, width: 11)
                                set2 = true
                            }
                        }
                        if set2 {
                            writer.setBit(first1 + 0)
                            set1 = true
                        }
                    }
                    do {
                        var set3 = false
                        do {
                            let value3 = try Self.__wire3(self.arena.y, paths, at)
                            let held3 = try Self.__wire3(baseline.arena.y, paths, at)
                            if value3 != held3 {
                                try writer.write(value3, width: 11)
                                set3 = true
                            }
                        }
                        if set3 {
                            writer.setBit(first1 + 1)
                            set1 = true
                        }
                    }
                    if self.arena.z != 0 { throw GesWireError(code: GesWireError.typeMismatch, path: paths[at + 1]) }
                    if !set1 { writer.rewind(to: first1) }
                }
                if set1 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set4 = false
                if try __writeKeyed4(baseline, &writer, paths, at) { set4 = true }
                if set4 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set19 = false
                if self.hasBadge != baseline.hasBadge {
                    try writer.write(self.hasBadge ? 1 : 0, width: 1)
                    if self.hasBadge {
                        try self.badge.__writeFields(&writer, paths, at + 20)
                    }
                    set19 = true
                } else if self.hasBadge {
                    let presence19 = writer.bitPosition
                    try writer.write(1, width: 1)
                    do {
                        let start19 = writer.bitPosition
                        if try self.badge.__writeDelta(baseline.badge, &writer, paths, at + 20, false) {
                            set19 = true
                        } else {
                            writer.rewind(to: start19)
                        }
                    }
                    if !set19 { writer.rewind(to: presence19) }
                }
                if set19 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            return changed
        }

        func __readDelta(_ baseline: World, _ reader: inout GesBitReader, _ paths: [String], _ at: Int, _ top: Bool) throws(GesWireError) -> Bool {
            let fieldCount = 4
            try reader.require(fieldCount, path: at == 0 ? "" : paths[at - 1])
            let changeBits = reader.bitPosition
            reader.seek(to: changeBits + fieldCount)
            var changed = false
            var ordinal = 0
            do {
                let payload0 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set0 = try reader.read(1, path: paths[at + 0]) == 1
                reader.seek(to: payload0)
                if set0 {
                    do {
                        let held0 = try Self.__wire0(baseline.tick, paths, at)
                        let value0 = try Self.__read0(&reader, paths, at)
                        if value0 == held0 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 0]) }
                        self.tick = Self.__value0(value0)
                    }
                    changed = true
                } else {
                    self.tick = baseline.tick
                }
                ordinal += 1
            }
            do {
                let payload1 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set1 = try reader.read(1, path: paths[at + 1]) == 1
                reader.seek(to: payload1)
                if set1 {
                    do {
                        try reader.require(2, path: paths[at + 1])
                        let bits1 = reader.bitPosition
                        reader.seek(to: bits1 + 2)
                        var changed1 = false
                        do {
                            let payload2 = reader.bitPosition
                            reader.seek(to: bits1 + 0)
                            let set2 = try reader.read(1, path: paths[at + 2]) == 1
                            reader.seek(to: payload2)
                            if set2 {
                                do {
                                    let held2 = try Self.__wire2(baseline.arena.x, paths, at)
                                    let value2 = try Self.__read2(&reader, paths, at)
                                    if value2 == held2 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 2]) }
                                    self.arena.x = Self.__value2(value2)
                                }
                                changed1 = true
                            } else {
                                self.arena.x = baseline.arena.x
                            }
                        }
                        do {
                            let payload3 = reader.bitPosition
                            reader.seek(to: bits1 + 1)
                            let set3 = try reader.read(1, path: paths[at + 3]) == 1
                            reader.seek(to: payload3)
                            if set3 {
                                do {
                                    let held3 = try Self.__wire3(baseline.arena.y, paths, at)
                                    let value3 = try Self.__read3(&reader, paths, at)
                                    if value3 == held3 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 3]) }
                                    self.arena.y = Self.__value3(value3)
                                }
                                changed1 = true
                            } else {
                                self.arena.y = baseline.arena.y
                            }
                        }
                        self.arena.z = 0
                        if !changed1 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                    }
                    changed = true
                } else {
                    self.arena = baseline.arena
                }
                ordinal += 1
            }
            do {
                let payload4 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set4 = try reader.read(1, path: paths[at + 4]) == 1
                reader.seek(to: payload4)
                if set4 {
                    try __readKeyed4(baseline, &reader, paths, at)
                    changed = true
                } else {
                    self.bots.removeAll(keepingCapacity: true)
                    for index4 in 0..<baseline.bots.count {
                        if index4 == self.__botsPool.count { self.__botsPool.append(World_Bot()) }
                        let item4 = self.__botsPool[index4]
                        item4.copy(from: baseline.bots[index4])
                        self.bots.append(item4)
                    }
                }
                ordinal += 1
            }
            do {
                let payload19 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set19 = try reader.read(1, path: paths[at + 19]) == 1
                reader.seek(to: payload19)
                if set19 {
                    let present19 = try reader.read(1, path: paths[at + 19]) == 1
                    if !present19 && !baseline.hasBadge { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 19]) }
                    self.hasBadge = present19
                    if present19 && baseline.hasBadge {
                        if !(try self.badge.__readDelta(baseline.badge, &reader, paths, at + 20, false)) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 19]) }
                    } else if present19 {
                        try self.badge.__readFields(&reader, paths, at + 20)
                    }
                    changed = true
                } else {
                    self.hasBadge = baseline.hasBadge
                    self.badge.copy(from: baseline.badge)
                }
                ordinal += 1
            }
            return changed
        }
    }

    /// The schema `:World_Body`, read and written without allocation.
    struct World_Body: Sendable {
        /// The schema hash, independent of parameter values.
        static let schemaHash: UInt64 = 0x3068484dfbaf015f
        /// The hash over the schema hash and the parameter values this code was generated with.
        static let bindingHash: UInt64 = 0x1da402070665aa53
        /// The size of the largest encoding in bytes.
        static let maxByteCount = 2
        static let __paths: [String] = [
            "mass",
            "hull",
        ]

        /// The field `mass`, in kilogram.
        var mass: Double = 0.0

        /// The field `hull`.
        var hull: HullTag = .light

        /// Creates a record with every field at its zero value.
        init() {}

        /// Writes this record into a buffer; `maxByteCount` bytes always suffice.
        /// - Returns: The number of bytes written.
        /// - Throws: `GesWireError` when a value does not fit its field or the buffer is too small.
        func write(into buffer: UnsafeMutableRawBufferPointer) throws(GesWireError) -> Int {
            var writer = GesBitWriter(into: buffer)
            try __writeFields(&writer, Self.__paths, 0)
            return try writer.finish()
        }

        /// Writes this record into a new array of its exact size.
        /// - Throws: `GesWireError` when a value does not fit its field.
        func encoded() throws(GesWireError) -> [UInt8] {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(Self.maxByteCount, 1), alignment: 8)
            defer { buffer.deallocate() }
            let count = try write(into: buffer)
            return Array(buffer[0..<count])
        }

        /// Reads a record from untrusted data into this instance. After an error its values are unspecified.
        /// - Parameters:
        ///   - data: The data; it may continue after the record.
        ///   - byteLimit: An optional limit on the bytes of this record.
        /// - Returns: The number of bytes the record occupies.
        /// - Throws: `GesWireError` when the data is no valid record.
        @discardableResult
        mutating func read(from data: UnsafeRawBufferPointer, byteLimit: Int = .max) throws(GesWireError) -> Int {
            var reader = GesBitReader(data: data, byteLimit: byteLimit)
            try __readFields(&reader, Self.__paths, 0)
            return try reader.finish()
        }

        /// Reads a record from bytes into this instance. After an error its values are unspecified.
        /// - Returns: The number of bytes the record occupies.
        /// - Throws: `GesWireError` when the bytes are no valid record.
        @discardableResult
        mutating func read(from bytes: [UInt8], byteLimit: Int = .max) throws(GesWireError) -> Int {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
            defer { buffer.deallocate() }
            buffer.copyBytes(from: bytes)
            return try read(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), byteLimit: byteLimit)
        }

        func __writeFields(_ writer: inout GesBitWriter, _ paths: [String], _ at: Int) throws(GesWireError) {
            try writer.write(
                try GesWireRules.quantizedIndex(self.mass, lowerValue: Double(bitPattern: 0x0000000000000000), upperValue: Double(bitPattern: 0x408f400000000000), tenPower: 1.0, numerator: 1.0, lower: 0, path: paths[at + 0]),
                width: 10
            )
            try writer.write(UInt64(self.hull.rawValue), width: 1)
        }

        mutating func __readFields(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) {
            do {
                let index = try reader.read(10, path: paths[at + 0])
                if index > 1000 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 0]) }
                self.mass = GesWireRules.quantizedValue(index, lower: 0, numerator: 1, tenPower: 1.0)
            }
            do {
                let index = try reader.read(1, path: paths[at + 1])
                self.hull = HullTag(rawValue: UInt8(index))!
            }
        }

        private static func __wire0(_ value: Double, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            try GesWireRules.quantizedIndex(value, lowerValue: Double(bitPattern: 0x0000000000000000), upperValue: Double(bitPattern: 0x408f400000000000), tenPower: 1.0, numerator: 1.0, lower: 0, path: paths[at + 0])
        }

        private static func __read0(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(10, path: paths[at + 0])
            if wire > 1000 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 0]) }
            return wire
        }

        private static func __value0(_ wire: UInt64) -> Double { GesWireRules.quantizedValue(wire, lower: 0, numerator: 1, tenPower: 1.0) }

        private static func __wire1(_ value: HullTag, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            UInt64(value.rawValue)
        }

        private static func __read1(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(1, path: paths[at + 1])
